/**
 * BackupVerify - Checks whether recent backup jobs have succeeded.
 * Reads the backup status DCI and raises an alarm if stale or failed.
 */

local node = $node;
local maxAgeHours = 26; // Alert if no successful backup in 26 hours

local lastBackup = GetDCIValue(node, 'Custom.Backup.LastSuccessTimestamp');
local lastStatus = GetDCIValue(node, 'Custom.Backup.LastStatus');

if (lastBackup == null)
{
  CreateAlarm(node, 100003, 'Backup status unknown - DCI not collecting', '');
  return 'UNKNOWN';
}

local ageSeconds = time() - lastBackup;
local ageHours = ageSeconds / 3600;

if (lastStatus != 'SUCCESS')
{
  CreateAlarm(node, 100003, 'Last backup failed: ' + lastStatus, '');
  return 'FAILED';
}

if (ageHours > maxAgeHours)
{
  CreateAlarm(node, 100003, 'No successful backup in ' + ceil(ageHours) + ' hours', '');
  return 'STALE';
}

return 'OK';
